// Put the uploaded receipt under the binary key "data" so the AI step can read it.
return $input.all().map(item => {
  const binary = item.binary || {};
  const keys = Object.keys(binary);
  if (keys.length === 0) return { json: item.json };
  return { json: item.json, binary: { data: binary[keys[0]] } };
});

