// ===== Company reimbursement policy (edit these rules) =====
const POLICY = {
  mealLimitPerPerson: 2000,                  // max meal spend per person covered
  disallowedCategories: ['alcohol'],          // never reimbursable
  allowedCategories: ['office_supplies', 'accommodation'],
  purposeRequiredCategories: ['travel'],      // need a business purpose
  reviewCategories: ['entertainment', 'other'] // always sent for manual review
};
// ===========================================================

const form = $('Submit Expense Receipt').first().json;
const receipt = ($('Read Receipt').first().json.output) || {};
const previous = $input.all().filter(i => i.json && i.json.receipt_key);

const currency = receipt.currency || 'INR';
const money = n => currency + ' ' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const attendees = Math.max(1, Number(form.attendees) || 1);
const purpose = String(form.business_purpose || '').trim();
const items = Array.isArray(receipt.line_items) ? receipt.line_items : [];
const receiptKey = String(receipt.merchant || '').toLowerCase().trim() + '|' + (receipt.receipt_date || '') + '|' + Number(receipt.total_amount || 0).toFixed(2);

const receiptIssues = [];
if (receipt.is_readable === false) receiptIssues.push('Receipt image is not legible.');
if (!receipt.merchant) receiptIssues.push('Merchant name is missing.');
if (!receipt.receipt_date) receiptIssues.push('Receipt date is missing.');
if (!Number(receipt.total_amount)) receiptIssues.push('Total amount is missing.');
if (items.length === 0) receiptIssues.push('No line items could be read.');
const isDuplicate = previous.length > 0;
if (isDuplicate) receiptIssues.push('Possible duplicate: a receipt with the same merchant, date and total was already submitted.');

const mealLimit = POLICY.mealLimitPerPerson * attendees;
const mealTotal = items.filter(i => i.category === 'meals').reduce((s, i) => s + Number(i.amount || 0), 0);
const mealOver = mealTotal > mealLimit;

const checked = items.map(i => {
  const cat = i.category || 'other';
  let status = 'ALLOWED';
  let reason = 'Within policy.';
  if (POLICY.disallowedCategories.includes(cat)) {
    status = 'DISALLOWED'; reason = 'Category "' + cat + '" is not reimbursable.';
  } else if (cat === 'meals') {
    if (mealOver) { status = 'NEEDS REVIEW'; reason = 'Meal total ' + money(mealTotal) + ' exceeds the limit of ' + money(mealLimit) + ' (' + attendees + ' person(s)) by ' + money(mealTotal - mealLimit) + '.'; }
  } else if (POLICY.purposeRequiredCategories.includes(cat)) {
    if (purpose.length < 5) { status = 'NEEDS REVIEW'; reason = 'Business purpose is required for ' + cat + ' expenses.'; }
  } else if (POLICY.reviewCategories.includes(cat)) {
    status = 'NEEDS REVIEW'; reason = 'Category "' + cat + '" requires manager review.';
  } else if (!POLICY.allowedCategories.includes(cat)) {
    status = 'NEEDS REVIEW'; reason = 'No policy rule for this category.';
  }
  return { description: i.description || '', quantity: i.quantity || 1, amount: Number(i.amount || 0), category: cat, status, reason };
});

const flagged = checked.filter(i => i.status !== 'ALLOWED');
const flaggedAmount = flagged.reduce((s, i) => s + i.amount, 0);
const hasDisallowed = checked.some(i => i.status === 'DISALLOWED');
let overall = 'COMPLIANT';
if (isDuplicate || hasDisallowed) overall = 'NON-COMPLIANT';
else if (flagged.length > 0 || receiptIssues.length > 0) overall = 'NEEDS REVIEW';

let allowedAmount = checked.filter(i => i.status === 'ALLOWED').reduce((s, i) => s + i.amount, 0);
if (mealOver) allowedAmount += mealLimit; // meals reimbursable up to the limit if approved
if (isDuplicate) allowedAmount = 0;

const color = { 'ALLOWED': '#1a7f37', 'NEEDS REVIEW': '#b26a00', 'DISALLOWED': '#c62828' };
const rows = checked.map(i =>
  '<tr><td>' + i.description + '</td><td>' + i.category + '</td><td align="right">' + money(i.amount) +
  '</td><td style="color:' + color[i.status] + ';font-weight:bold">' + i.status + '</td><td>' + i.reason + '</td></tr>'
).join('');
const issuesHtml = receiptIssues.length ? '<p><b>Receipt issues:</b></p><ul>' + receiptIssues.map(x => '<li>' + x + '</li>').join('') + '</ul>' : '';

const html =
  '<h2>Expense compliance check: ' + overall + '</h2>' +
  '<p><b>Employee:</b> ' + (form.employee_name || '') + ' (' + (form.employee_email || '') + ')<br>' +
  '<b>Business purpose:</b> ' + purpose + '<br>' +
  '<b>Merchant:</b> ' + (receipt.merchant || '-') + '<br>' +
  '<b>Date:</b> ' + (receipt.receipt_date || '-') + '<br>' +
  '<b>Claimed total:</b> ' + money(receipt.total_amount) + '<br>' +
  '<b>Flagged items:</b> ' + flagged.length + ' (' + money(flaggedAmount) + ')<br>' +
  '<b>Reimbursable if approved as-is:</b> ' + money(allowedAmount) + '</p>' +
  issuesHtml +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">' +
  '<tr><th>Item</th><th>Category</th><th>Amount</th><th>Status</th><th>Reason</th></tr>' + rows + '</table>' +
  '<p>Please approve, reject, or follow up with the employee.</p>';

return [{ json: {
  receipt_key: receiptKey,
  employee_name: form.employee_name || '',
  employee_email: form.employee_email || '',
  manager_email: form.manager_email || '',
  merchant: receipt.merchant || '',
  receipt_date: receipt.receipt_date || '',
  total_amount: Number(receipt.total_amount || 0),
  overall_status: overall,
  flagged_count: flagged.length,
  flagged_amount: flaggedAmount,
  reimbursable_amount: allowedAmount,
  line_items_json: JSON.stringify(checked),
  receipt_issues: receiptIssues,
  report_html: html
} }];
